import{_ as o,o as r,c as e,a5 as a}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse(`{"title":"第八章：实现动态导入（import()）与异步代码分割（Code Splitting）","description":"太棒了，我们正式进入： 🧩 ✅ 本章目标： 支持在模块中写 const mod await import('./a.mjs') 动态加载依赖模块而非一开始全部打包 实现 基础的代码分割 ：只加载需要的模块 💡 背景：动态导入是啥？ // ✅ 动态导入，不会在程序启动时立刻加载co。","frontmatter":{"title":"第八章：实现动态导入（import()）与异步代码分割（Code Splitting）","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"太棒了，我们正式进入： 🧩 ✅ 本章目标： 支持在模块中写 const mod await import('./a.mjs') 动态加载依赖模块而非一开始全部打包 实现 基础的代码分割 ：只加载需要的模块 💡 背景：动态导入是啥？ // ✅ 动态导入，不会在程序启动时立刻加载co。","sidebarWeight":45,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/第八章：实现动态导入（import()）与异步代码分割（Code Splitting）.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第八章：实现动态导入（import()）与异步代码分割（Code Splitting）.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第八章：实现动态导入（import()）与异步代码分割（Code Splitting）.md"}`),s={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第八章：实现动态导入（import()）与异步代码分割（Code Splitting）.md"};function n(i,t,l,d,p,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<div><h1 id="第八章-实现动态导入-import-与异步代码分割-code-splitting" tabindex="-1">第八章：实现动态导入（import()）与异步代码分割（Code Splitting） <a class="header-anchor" href="#第八章-实现动态导入-import-与异步代码分割-code-splitting" aria-label="Permalink to &quot;第八章：实现动态导入（import()）与异步代码分割（Code Splitting）&quot;">​</a></h1><blockquote><p>本节目标：理解“第八章：实现动态导入（import()）与异步代码分割（Code Splitting）”的核心思路，并能把它用于实际开发或面试表达。 太棒了，我们正式进入：</p></blockquote><p><strong>🧩</strong> ✅ 本章目标：</p><ul><li>支持在模块中写 const mod = await import(&#39;./a.mjs&#39;)</li><li>动态加载依赖模块而非一开始全部打包</li><li>实现<strong>基础的代码分割</strong>：只加载需要的模块</li></ul><p><strong>💡</strong> <strong>背景：动态导入是啥？</strong> // ✅ 动态导入，不会在程序启动时立刻加载const mod = await import(&#39;./a.mjs&#39;);console.log(mod.foo); 相比静态 import ... from ...，动态导入允许你 <strong>按需懒加载模块</strong>，并触发<strong>异步加载流程</strong>，适用于：</p><ul><li>路由懒加载</li><li>功能分块（组件、插件）</li><li>异步初始化流程（如编辑器或图表库）</li></ul><p><strong>🧱</strong> <strong>项目结构</strong> dynaloader/├── src/│ ├── main.mjs│ └── feature.mjs├── loader.js # 支持 import() 的 loader└── run.js # 启动入口</p><p><strong>✍️</strong> <strong>src/feature.mjs</strong> export const heavy = &#39;This is a heavy feature loaded lazily&#39;; <strong>✍️</strong> <strong>src/main.mjs</strong> console.log(&#39;Main loaded&#39;); const mod = await import(&#39;./feature.mjs&#39;);console.log(&#39;Dynamically imported:&#39;, mod.heavy);</p><p><strong>🔧</strong> <strong>loader.js — 实现 import() 运行时动态加载</strong> const fs = require(&#39;fs&#39;);const path = require(&#39;path&#39;);const acorn = require(&#39;acorn&#39;); const moduleCache = new Map(); async function loadModule(filePath) { const absPath = path.resolve(__dirname, filePath); if (moduleCache.has(absPath)) return moduleCache.get(absPath); const code = fs.readFileSync(absPath, &#39;utf-8&#39;); // 构造 async 函数支持 import() const wrapped = <code>return async function(dynamicImport, exports) { ${code // 转换 export const foo = ... → exports.foo = ... .replace(/export\\s+const\\s+(\\w+)\\s*=\\s*(.*);/g, (_, name, val) =\\&gt; { return</code>const ${name} = ${val}; exports.${name} = ${name};<code>; }) // 替换 import() 为 dynamicImport() 调用 .replace(/import\\(([&#39;&quot;].+?[&#39;&quot;])\\)/g, (_, path) =\\&gt; { return </code>await dynamicImport(${path})<code>; })} } </code>; const exports = {}; const factory = new Function(wrapped)(); const dynamicImport = async (targetPath) =&gt; { const fullPath = path.resolve(path.dirname(absPath), targetPath.slice(1, -1) + &#39;.mjs&#39;); return await loadModule(fullPath); }; await factory(dynamicImport, exports); moduleCache.set(absPath, exports); return exports;} module.exports = { loadModule };</p><p><strong>🚀</strong> <strong>run.js — 执行入口</strong> const { loadModule } = require(&#39;./loader&#39;); (async () =&gt; { await loadModule(&#39;./src/main.mjs&#39;);})();</p><p><strong>✅</strong> <strong>运行并观察结果</strong> node run.js 输出应该为： Main loadedDynamically imported: This is a heavy feature loaded lazily</p><p><strong>🔍</strong> <strong>本章实现要点</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>功能点</strong></td><td><strong>实现方式</strong></td></tr><tr><td>动态导入 import()</td><td>替换为 await dynamicImport(...) 并绑定加载器</td></tr><tr><td>支持模块导出</td><td>exports.xxx = xxx</td></tr><tr><td>模块缓存</td><td>使用 Map 防止重复加载</td></tr><tr><td>懒加载模块</td><td>动态执行才加载对应代码</td></tr><tr><td>模拟 code splitting</td><td>各模块分别存在于 .mjs 文件</td></tr></tbody></table><p><strong>✅</strong> <strong>本章成果</strong></p><ul><li>✔ 模拟了动态导入 import()</li><li>✔ 懒加载模块，提升加载性能</li><li>✔ 模拟代码分割（每个模块一个 chunk）</li></ul><p><strong>🔮</strong> <strong>下一章预告（第九章）</strong> 我们现在已经有了：</p><ul><li>静态 import/export 分析</li><li>模块依赖图构建</li><li>Tree Shaking</li><li>top-level await</li><li>动态导入（import）</li><li>模块缓存</li></ul><p>接下来我们可以尝试： <strong>第九章：模拟一个真实的 Rollup/Vite 打包器接口（CLI）和输出 bundle 文件 + map</strong> 你是否想继续？我会在第九章中整合前面内容，让你拥有一个基础但完整的打包工具 🎁 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const u=o(s,[["render",n]]);export{g as __pageData,u as default};
